def fix_romanian(text: str) -> str:
    text = text.translate(str.maketrans({
        "ş": "ș",
        "Ş": "Ș",
        "ţ": "ț",
        "Ţ": "Ț",
    }))
    for old, new in (
        ("s\u0327", "ș"),
        ("S\u0327", "Ș"),
        ("t\u0327", "ț"),
        ("T\u0327", "Ț"),
    ):
        text = text.replace(old, new)
    return text
